public static String convertDatesToWeekdays(String date) {
    // Check if the input date is in the correct format
    if (!date.matches("\\d{2} \\d{2} \\d{4}")) {
        throw new IllegalArgumentException("Invalid date format");
    }

    // Extract the month, day, and year from the input date
    int month = Integer.parseInt(date.substring(0, 2));
    int day = Integer.parseInt(date.substring(3, 5));
    int year = Integer.parseInt(date.substring(6));

    // Create a Calendar object for the input date
    Calendar calendar = new GregorianCalendar(year, month - 1, day);

    // Get the weekday of the input date
    int weekday = calendar.get(Calendar.DAY_OF_WEEK);

    // Return the weekday of the input date
    switch (weekday) {
        case Calendar.SUNDAY:
            return "Sunday";
        case Calendar.MONDAY:
            return "Monday";
        case Calendar.TUESDAY:
            return "Tuesday";
        case Calendar.WEDNESDAY:
            return "Wednesday";
        case Calendar.THURSDAY:
            return "Thursday";
        case Calendar.FRIDAY:
            return "Friday";
        case Calendar.SATURDAY:
            return "Saturday";
        default:
            throw new IllegalStateException("Invalid weekday");
    }
}

