public String sortString(String s) {
    // Initialize an empty string to store the sorted result
    String result = "";

    // Loop through the characters of the input string
    for (int i = 0; i < s.length(); i++) {
        // Get the current character
        char c = s.charAt(i);

        // If the character is not already in the result, append it
        if (!result.contains(c)) {
            result += c;
        }

        // If the character is already in the result, find the next occurrence
        else {
            // Get the index of the next occurrence of the character
            int index = result.indexOf(c, i);

            // If the next occurrence is not the last character, append it
            if (index != result.length() - 1) {
                result += result.charAt(index + 1);
            }
        }
    }

    // Reverse the result string
    result = new StringBuilder(result).reverse().toString();

    return result;
}

